def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

pairs = []
for p in range(3, 400):
    if p % 2 != 0 and is_prime(p):
        q = 800 - p
        # Check if q is prime, q > p, and q is odd (q > 2)
        if q > p and is_prime(q):
            # Since p is odd and 800 is even, q must be odd.
            pairs.append((p, q))

print("Valid pairs (p, q) for Case 1 (p+q=800):")
for pair in pairs:
    print(pair)

